parameters.jsCode:
// 1. استخراج النص الذي أنتجه Gemini وتحويله من نص إلى كائن JSON حقيقي
const aiResponseRaw = items[0].json.output;
// إزالة أي علامات تفوق النص (Markdown) قد يضيفها Gemini أحياناً
const cleanedJson = aiResponseRaw.replace(/```json/g, "").replace(/```/g, "").trim();
const aiData = JSON.parse(cleanedJson);

// 2. جلب البيانات الأصلية من الـ Webhook (مثل الصورة والاسم والروابط)
// ملاحظة: n8n يتيح الوصول للبيانات السابقة عبر $node
const originalData = $("Webhook").first().json.body;

// 3. دمج كل شيء في مخرج واحد مرتب
return {
  name: originalData.name,
  email: originalData.email,
  phone: originalData.phone,
  photo: originalData.photo, // الصورة الأصلية بصيغة Base64
  linkedin: originalData.linkedin || "",
  github: originalData.github || "",

  // البيانات المحسنة من Gemini
  summary: aiData.summary_professional,
  experiences: aiData.experiences_refined,
  skills: aiData.skills_categorized
};

parameters.html_content:
=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        @page { size: A4; margin: 0; }
        body {
            font-family: 'Helvetica', Arial, sans-serif;
            margin: 0; padding: 0; color: #333; font-size: 12px; line-height: 1.4;
        }
        /* الهيدر الأزرق */
        .header {
            background-color: #1a4a7c;
            color: white;
            display: table;
            width: 100%;
            height: 160px;
        }
        .header-left {
            display: table-cell;
            width: 160px;
            vertical-align: middle;
            background-color: #fff;
            border-right: 4px solid #1a4a7c;
        }
        .header-left img {
            width: 100%;
            height: 160px;
            object-fit: cover;
        }
        .header-right {
            display: table-cell;
            vertical-align: middle;
            padding: 20px 30px;
        }
        .header-right h1 {
            margin: 0 0 10px 0;
            font-size: 28px;
            text-transform: uppercase;
            letter-spacing: 2px;
        }
        .contact-grid {
            display: block;
            font-size: 11px;
        }
        .contact-item { margin-bottom: 2px; }

        /* الأقسام */
        .container { padding: 30px 40px; }
        h2 {
            color: #000;
            font-size: 16px;
            border-bottom: 2px solid #1a4a7c;
            margin: 20px 0 10px 0;
            padding-bottom: 5px;
            text-transform: uppercase;
        }
        .section-content { margin-bottom: 15px; }

        /* الخبرات */
        .exp-header {
            font-weight: bold;
            display: flex;
            justify-content: space-between;
            margin-bottom: 5px;
        }
        .tools { font-weight: bold; color: #1a4a7c; margin-top: 5px; }

        /* عمودين في الأسفل */
        .row { display: flex; width: 100%; gap: 40px; }
        .column { flex: 1; }

        ul { padding-left: 18px; margin: 5px 0; }
        li { margin-bottom: 3px; }
    </style>
</head>
<body>

    <div class="header">
        <div class="header-left">
            <img src="{{ $json.photo }}">
        </div>
        <div class="header-right">
            <h1>{{ $json.name }}</h1>
            <div class="contact-grid">
                <div class="contact-item"><b>Address:</b> ................................</div>
                <div class="contact-item"><b>Phone:</b> {{ $json.phone }}</div>
                <div class="contact-item"><b>Email:</b> {{ $json.email }}</div>
                <div class="contact-item"><b>LinkedIn:</b> {{ $json.linkedin || 'N/A' }}</div>
                <div class="contact-item"><b>GitHub:</b> {{ $json.github || 'N/A' }}</div>
            </div>
        </div>
    </div>

    <div class="container">
        <div class="section">
            <h2>Profil</h2>
            <p>{{ $json.summary }}</p>
        </div>

        <div class="section">
            <h2>Experience</h2>
            {{ $json.experiences.map(exp => `
                <div class="section-content">
                    <div style="display: flex; justify-content: space-between; font-weight: bold;">
                        <span>${exp.poste_experience} | ${exp.entreprise}</span>
                        <span>${exp.date_debut} – ${exp.date_fin}</span>
                    </div>
                    <ul>
                        <li>${exp.description_experience}</li>
                    </ul>
                    <div class="tools">Tools : ${exp.tools || 'React, Java, Spring Boot'}</div>
                </div>
            `).join('') }}
        </div>

        <div class="section">
            <h2>Formation</h2>
            <div style="display: flex; justify-content: space-between; font-weight: bold;">
                <span>Master en Informatique</span>
                <span>SUPMTI, Rabat | 2023</span>
            </div>
        </div>

        <div class="row">
            <div class="column">
                <h2>Projets</h2>
                <ul>
                    <li><b>Nom du projet :</b> Description technique...</li>
                </ul>
            </div>
            <div class="column">
                <h2>Compétences Techniques</h2>
                <ul>
                    {{ $json.skills.map(skill => `<li>${skill}</li>`).join('') }}
                </ul>
            </div>
        </div>
    </div>

</body>
</html>
